// A TCP port that is free for a server listening on all interfaces and for the clients
// that connect to it through the loopback ("localhost", 127.0.0.1 or ::1).
//
// listen(0) is not enough for that: Node sets SO_REUSEADDR on every listening socket, so
// the system lets a server on all interfaces share a port with a server bound to one
// address (127.0.0.1:<port>), and the system chooses ports without looking at such
// servers. A client that connects to 127.0.0.1:<port> then reaches the foreign server,
// not ours (the same crosstalk that nr-test-utils/supertest avoids; here seen with a
// dev tool listening on 127.0.0.1). The port is therefore also tried on the loopback
// addresses, where a foreign listener makes listen fail.

const net = require("net");

function listen(server, port, host) {
    return new Promise((resolve, reject) => {
        server.once("error", reject);
        const args = host ? [port, host] : [port];
        server.listen(...args, () => {
            server.removeListener("error", reject);
            resolve(server.address().port);
        });
    });
}

function close(server) {
    return new Promise(resolve => server.close(() => resolve()));
}

// true when nothing listens on <port> on the loopback addresses. IPv6 is skipped only
// when the machine has none (EADDRNOTAVAIL, EAFNOSUPPORT); any other error is thrown.
async function isFreeOnLoopback(port) {
    for (const host of ["127.0.0.1", "::1"]) {
        const probe = net.createServer();
        try {
            await listen(probe, port, host);
        } catch (err) {
            if (err.code === "EADDRINUSE") {
                return false;
            }
            if (host === "::1" && (err.code === "EADDRNOTAVAIL" || err.code === "EAFNOSUPPORT")) {
                continue;
            }
            throw err;
        }
        await close(probe);
    }
    return true;
}

// Resolves with a port that was free for all interfaces and the loopback addresses just
// now. The port is released: it can be taken by someone else before the caller uses it
// (a short window; sockets are assigned ports one after another, not at random).
async function freePort(attempts = 20) {
    for (let i = 0; i < attempts; i++) {
        const probe = net.createServer();
        const port = await listen(probe, 0);
        // the probe on all interfaces is open while the loopback is checked: the port
        // cannot be given to anyone else meanwhile
        const free = await isFreeOnLoopback(port);
        await close(probe);
        if (free) {
            return port;
        }
    }
    throw new Error("nr-test-utils/free-port: no free port in " + attempts + " attempts");
}

// Starts `server` on all interfaces on a free port and resolves with the port. Tries
// another port when the chosen one was taken in the meantime.
async function listenOnFreePort(server, attempts = 10) {
    for (let i = 1; ; i++) {
        const port = await freePort();
        try {
            return await listen(server, port);
        } catch (err) {
            if (err.code !== "EADDRINUSE" || i >= attempts) {
                throw err;
            }
        }
    }
}

module.exports = { freePort, listenOnFreePort, isFreeOnLoopback };
